if(string.IsNullOrEmpty(SessionState.GetString("Bulldozer.Mining.TestSavePath","")))throw new System.Exception("Isolated fresh save required");
var ui=Bulldozer.UI.QuarryGameUI.Instance;var p=ui.player;var e=ui.equipment;var prod=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.MiningProduction>();var guide=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.QuarryGuidance>();var mining=p.visual.GetComponent<Bulldozer.Player.MinerMining>();var rocks=UnityEngine.Object.FindObjectsByType<Bulldozer.Player.MineableRock>(FindObjectsSortMode.None);var path=new UnityEngine.AI.NavMeshPath();var filter=new UnityEngine.AI.NavMeshQueryFilter{agentTypeID=guide.agentTypeId,areaMask=UnityEngine.AI.NavMesh.AllAreas};
float started=Time.realtimeSinceStartup,next=0,goalAt=0,lastProgress=0;int lastRocks=0,lastDeliveries=0;string goal="";Vector3 destination=Vector3.zero;Bulldozer.Player.MineableRock target=null;float firstUpgrade=-1,firstDelivery=-1;var log=new System.Collections.Generic.List<string>();p.autoMine=false;EditorApplication.isPaused=false;Time.captureDeltaTime=0;int maxBatches=0,maxSetPass=0,maxParticles=0,maxAudio=0;long maxMemory=0;int samples=0;bool stopped=false;
bool Route(Vector3 end){if(!UnityEngine.AI.NavMesh.SamplePosition(p.transform.position,out var from,2,filter)||!UnityEngine.AI.NavMesh.SamplePosition(end,out var to,1,filter))return false;return UnityEngine.AI.NavMesh.CalculatePath(from.position,to.position,filter,path)&&path.status==UnityEngine.AI.NavMeshPathStatus.PathComplete;}
void Choose(string label,Vector3 pos,Bulldozer.Player.MineableRock rock=null){if(goal==label&&(destination-pos).sqrMagnitude<.05f)return;goal=label;destination=pos;target=rock;goalAt=Time.realtimeSinceStartup;p.autoMine=false;p.CancelMining();}
void MineNext(){float best=float.MaxValue;Vector3 at=Vector3.zero;Bulldozer.Player.MineableRock chosen=null;foreach(var r in rocks){if(!r||r.Depleted)continue;var b=r.HitCollider.bounds;var dirs=new[]{Vector3.back,Vector3.left,Vector3.right,Vector3.forward};foreach(var d in dirs){var candidate=r.naturalBoulder?r.transform.position+d*1.05f:b.center+Vector3.Scale(d,b.extents)+d*.65f;candidate.y=p.transform.position.y;float score=(candidate-p.transform.position).sqrMagnitude+(e.DamageLevel==0?Mathf.Max(0,r.maxHealth-3)*20:0);if(score>=best||!Route(candidate))continue;best=score;at=candidate;chosen=r;}}if(chosen)Choose("mine "+chosen.blockId,at,chosen);else Choose("wait",new Vector3(0,.03f,-3));}
EditorApplication.CallbackFunction tick=null;System.Action finish=()=>{p.autoMine=false;p.CancelMining();p.touchControls.Move=Vector2.zero;EditorApplication.update-=tick;var s=e.Snapshot;log.Add("FINAL elapsed="+(Time.realtimeSinceStartup-started).ToString("F1")+"s rocks="+s.depletedBlocks.Length+" hits="+mining.SuccessfulHits+" refined="+s.taskRefined+" deliveries="+s.trucksCompleted+" cash="+s.coins+" firstUpgrade="+firstUpgrade+"s firstDelivery="+firstDelivery+"s");log.Add("EDITOR MAX samples="+samples+" batches="+maxBatches+" setPass="+maxSetPass+" particles="+maxParticles+" activeAudio="+maxAudio+" memoryBytes="+maxMemory);System.IO.File.WriteAllLines("Maintenance/Mobile/first-session-report.txt",log);};
tick=()=>{if(!EditorApplication.isPlaying){EditorApplication.update-=tick;return;}try{float now=Time.realtimeSinceStartup;if(now<next)return;next=now+.12f;var s=e.Snapshot;float elapsed=now-started;
if(samples++%20==0){maxBatches=Mathf.Max(maxBatches,UnityEditor.UnityStats.batches);maxSetPass=Mathf.Max(maxSetPass,UnityEditor.UnityStats.setPassCalls);maxParticles=Mathf.Max(maxParticles,UnityEngine.Object.FindObjectsByType<ParticleSystem>(FindObjectsSortMode.None).Sum(x=>x.particleCount));maxAudio=Mathf.Max(maxAudio,UnityEngine.Object.FindObjectsByType<AudioSource>(FindObjectsSortMode.None).Count(x=>x.isPlaying));maxMemory=System.Math.Max(maxMemory,UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong());System.IO.File.WriteAllText("Maintenance/Mobile/first-session-status.txt",$"elapsed={elapsed:F1}s goal={goal} rocks={s.depletedBlocks.Length} refined={s.taskRefined} deliveries={s.trucksCompleted} cash={s.coins} position={p.transform.position} target={destination} firstUpgrade={firstUpgrade:F1}s firstDelivery={firstDelivery:F1}s");}
if(s.depletedBlocks.Length!=lastRocks||s.trucksCompleted!=lastDeliveries){lastProgress=now;log.Add($"{elapsed:F1}s rocks={s.depletedBlocks.Length} deliveries={s.trucksCompleted} cash={s.coins}");lastRocks=s.depletedBlocks.Length;lastDeliveries=s.trucksCompleted;}
if(firstUpgrade<0&&e.DamageLevel>0)firstUpgrade=elapsed;if(firstDelivery<0&&s.trucksCompleted>0)firstDelivery=elapsed;
if(elapsed>=360){log.Add((firstUpgrade>0&&firstUpgrade<120&&s.trucksCompleted>1&&s.taskRefined>0?"PASS ":"FAIL ")+"Six-minute walking session reaches starter upgrade, refinery and multiple deliveries");finish();return;}
if(ui.modal.gameObject.activeSelf){p.touchControls.Move=Vector2.zero;if(ui.modal.Busy)return;if(ui.upgradePage.activeSelf){if(e.DamageLevel==0&&e.Cash>=e.DamageCost)ui.buyButtons[0].onClick.Invoke();if(e.SpeedLevel==0&&e.Cash>=e.SpeedCost)ui.buyButtons[2].onClick.Invoke();if(e.CapacityLevel==0&&e.Cash>=e.CapacityCost)ui.buyButtons[1].onClick.Invoke();}ui.Close();goal="";return;}
if(p.InputBlocked)return;
if(e.DamageLevel==0&&e.Cash>=e.DamageCost||e.SpeedLevel==0&&s.trucksCompleted>0&&e.Cash>=e.SpeedCost||e.CapacityLevel==0&&s.trucksCompleted>0&&e.Cash>=e.CapacityCost)Choose("upgrade",ui.workbench.zone.bounds.center);
else if(s.items.Any(x=>x>=6))Choose("load",prod.sellZone.bounds.center);
else if(s.items.Length>0&&(e.IsFull||s.groundDrops.Length==0&&s.taskRocks>=2))Choose("deposit",prod.inputZone.bounds.center);
else if(s.refineryOutput.Length>0&&s.items.Length==0)Choose("collect",prod.outputZone.bounds.center);
else if(s.groundDrops.Length>0&&!e.IsFull){var d=s.groundDrops.OrderBy(x=>(x.position-p.transform.position).sqrMagnitude).First();Choose("pickup "+d.id,d.position);}
else if(target==null||target.Depleted||!goal.StartsWith("mine"))MineNext();
Vector3 delta=destination-p.transform.position;delta.y=0;
if(delta.magnitude<.24f){p.touchControls.Move=Vector2.zero;if(goal.StartsWith("mine")&&target){Vector3 facing=target.HitCollider.bounds.center-p.transform.position;facing.y=0;if(facing.sqrMagnitude>.01f)p.visual.rotation=Quaternion.LookRotation(facing);p.autoMine=true;}else if(goal=="upgrade")ui.Open("upgrades");}
else {p.autoMine=false;if(p.IsMining)p.CancelMining();if(Route(destination)){var corners=path.corners;Vector3 waypoint=destination;for(int i=1;i<corners.Length;i++){var d=corners[i]-p.transform.position;d.y=0;if(d.magnitude>.3f){waypoint=corners[i];break;}}var direction=waypoint-p.transform.position;direction.y=0;var local=Quaternion.Euler(0,-p.followCamera.Yaw,0)*direction.normalized;p.touchControls.Move=new Vector2(local.x,local.z)*Mathf.Clamp(delta.magnitude*2,.3f,1);}else{p.touchControls.Move=Vector2.zero;log.Add("FAIL no walking route to "+goal);finish();return;}}
if(now-goalAt>35){log.Add("FAIL stuck walking/working at "+goal+" pos="+p.transform.position+" target="+destination+" status="+mining.Status);finish();}
